import {renderScale} from './sid-scale.mjs';
import {initLongitudinal,updateLongitudinal} from './sid-longitudinal.mjs';
import {featuresAtLevel,changes,evidenceMatch,filterChanges,contextEvents} from './sid-model.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,cards,features,rows,selected,clinical,phylogeny;const date=s=>new Date(s.date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});const marker=s=>s.dateStatus==='conflicting'?' *':s.dateStatus==='received'?' †':'';
const pct=v=>v===0?'0':v*100<.001?'<0.001':(v*100).toFixed(3);const delta=v=>(v>0?'+':'')+(v!==0&&Math.abs(v)<.001?v.toExponential(2):v.toFixed(3));const fold=r=>r.fold===null?r.status:r.start===0?r.status:r.end===0?r.status:`${r.fold<.001?r.fold.toExponential(2):r.fold.toFixed(2)}×`;
const xAt=(s,left,right)=>{const t=data.samples.map(s=>Date.parse(s.date));return left+(Date.parse(s.date)-t[0])/(t.at(-1)-t[0])*(right-left)};
function timeline(){const a=+$('from').value,b=+$('to').value;const left=65,right=935,y=38;let svg='<svg viewBox="0 0 1000 105" role="img" aria-label="Five stool profiles on their reported dates; February and March dates are uncertain"><line x1="65" y1="38" x2="935" y2="38" stroke="#dce3db" stroke-width="3"/>';
svg+=`<line x1="${xAt(data.samples[a],left,right)}" y1="${y}" x2="${xAt(data.samples[b],left,right)}" y2="${y}" stroke="#166f60" stroke-width="4"/>`;
data.samples.forEach((s,i)=>{const x=xAt(s,left,right);svg+=`<circle cx="${x}" cy="${y}" r="${i===a||i===b?8:5}" fill="${i===a||i===b?'#166f60':'#a0b3a7'}" ${i>1?'stroke="#856244" stroke-dasharray="2 2" stroke-width="2"':''}><title>${s.id}: ${date(s)}. ${esc(s.dateNote)}</title></circle><text x="${x}" y="${i===3?82:65}" text-anchor="middle" font-size="12" fill="#193a38">${date(s)}${marker(s)}</text>`});$('timeline').innerHTML=svg+'</svg>'}
function updateInterval(origin){let a=+$('from').value,b=+$('to').value;if(a>=b){if(origin==='from'){$('to').value=String(Math.min(a+1,data.samples.length-1));if(a===data.samples.length-1)$('from').value=String(a-1)}else{$('from').value=String(Math.max(0,b-1));if(b===0)$('to').value='1'}}render()}
function render(){features=featuresAtLevel(data,$('level').value);rows=changes(features,+$('from').value,+$('to').value);selected=rows.find(r=>r.id===selected?.id)||rows.find(r=>r.genus==='Akkermansia')||rows[0];const a=data.samples[+$('from').value],b=data.samples[+$('to').value];$('intervalStatus').textContent=`${date(a)}${marker(a)} → ${date(b)}${marker(b)}. ${rows.filter(r=>r.delta>0).length} increases · ${rows.filter(r=>r.delta<0).length} decreases before feature filters. Observed composition changes; no causal attribution.`;timeline();renderTable();renderClinical()}
function settings(){return {abundance:Math.max(0,Math.min(100,+$('minAbundance').value||0)),minSamples:+$('minSamples').value,minDelta:Math.max(0,Math.min(100,+$('minDelta').value||0)),query:$('search').value,direction:$('direction').value}}
function visibleRows(){return filterChanges(rows,settings())}
function renderTable(){const visible=visibleRows();selected=visible.find(r=>r.id===selected?.id)||visible[0]||null;$('changeSummary').textContent=`${visible.length} of ${rows.length} features shown · presence counted across all 5 visits`;$('export').disabled=!visible.length;$('rows').innerHTML=visible.map(r=>`<tr class="${r.id===selected?.id?'selected':''}"><td><button data-id="${esc(r.id)}" aria-pressed="${r.id===selected?.id}">${esc(r.name)}</button><small>${$('level').value==='sgb'?`SGB ${r.id}`:`${r.sgbs.length} SGB${r.sgbs.length===1?'':'s'}`}${!r.resolved?' · unresolved':''}</small></td><td>${pct(r.start)}</td><td>${pct(r.end)}</td><td class="${r.delta>=0?'delta-up':'delta-down'}">${delta(r.delta)}</td><td>${esc(fold(r))}</td><td>${r.present} / 5</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No features match. Lower the thresholds or clear your search.</td></tr>';renderDetail();updateLongitudinal({data,clinical,features,selected,start:+$('from').value,end:+$('to').value,level:$('level').value});renderScale({data,phylogeny,start:+$('from').value,end:+$('to').value,level:$('level').value,selected,onSelect:(level,id)=>{$('level').value=level;$('minAbundance').value='0';$('minSamples').value='1';$('minDelta').value='0';$('search').value='';$('direction').value='all';selected={id};render()}})}
function renderClinical(){const scope=$('clinicalScope').value,a=scope==='interval'?+$('from').value:+scope,b=scope==='interval'?+$('to').value:+scope,start=data.samples[a],end=data.samples[b],padding=+$('nearbyDays').value;const entries=contextEvents(clinical.events,start.date,end.date,padding,$('eventCategory').value);$('clinicalStatus').textContent=`${date(start)}${marker(start)}${a===b?'':' → '+date(end)+marker(end)} · ${entries.length} source entries including ± ${padding} days. Dates describe documentation, not confirmed effects on the microbiome.`;$('clinicalEvents').innerHTML=entries.map(e=>`<article class="clinical-event"><div><span class="tag">${esc(e.relation)}</span><p><b>${esc(e.date)}${e.end_date?' → '+esc(e.end_date):''}</b></p></div><div><h3>${esc(e.title||e.subcategory)}${e.dose?' · '+esc(e.dose):''}</h3><p>${esc(e.category)}${e.subcategory?' / '+esc(e.subcategory):''} · ${esc(e.timeline)}</p><a href="${clinical.source}" target="_blank" rel="noopener">Source event table ↗</a></div></article>`).join('')||'<p class="empty">No entries found for this window and category. This does not establish that no treatment occurred.</p>'}
function renderDetail(){if(!selected){$('taxonTitle').textContent='No eligible feature';for(const id of ['taxonScope','observation','trajectory','visitValues','evidence'])$(id).innerHTML='';$('searchLink').removeAttribute('href');$('searchLink').textContent='Select an eligible feature to search';return}const r=selected,a=+$('from').value,b=+$('to').value;$('taxonTitle').textContent=r.name;$('taxonScope').textContent=`${$('level').value==='sgb'?`SGB ${r.id}`:`${r.sgbs.length} SGB${r.sgbs.length===1?'':'s'} aggregated`}${!r.resolved?' · no resolved taxonomic name':''}`;
$('observation').innerHTML=`<strong>${pct(r.start)}% → ${pct(r.end)}%</strong><p><b>${delta(r.delta)} percentage points</b> · ${esc(fold(r))}</p><p>${r.status}. This is a share of reported abundance, not a measured change in cell count.</p>`;
const w=520,h=260,l=48,right=490,top=20,bottom=205,max=Math.max(...r.values)*100*1.15||1;const y=v=>bottom-v*100/max*(bottom-top);let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Reported abundance share across five visits for ${esc(r.name)}"><text x="${l}" y="12" fill="#677b77" font-size="11">Share of reported abundance (%)</text>`;
for(let i=0;i<4;i++){const yy=bottom-(bottom-top)*i/3;svg+=`<line x1="${l}" y1="${yy}" x2="${right}" y2="${yy}" stroke="#dce3db"/><text x="${l-7}" y="${yy+4}" text-anchor="end" font-size="10" fill="#677b77">${(max*i/3).toFixed(max<.1?3:1)}</text>`}
svg+=`<polyline points="${r.values.map((v,i)=>`${xAt(data.samples[i],l,right)},${y(v)}`).join(' ')}" fill="none" stroke="#8ca99b" stroke-width="2"/>`;
r.values.forEach((v,i)=>{const s=data.samples[i],x=xAt(s,l,right);if(i>1)svg+=`<line x1="${x}" y1="${top+5}" x2="${x}" y2="${bottom}" stroke="#c3b29a" stroke-dasharray="3 5"/>`;svg+=`<circle cx="${x}" cy="${y(v)}" r="${i===a||i===b?6:4}" fill="${i===a||i===b?'#166f60':'#a1b6a8'}" stroke="#fffefa" stroke-width="2"><title>${date(s)}${marker(s)}: ${pct(v)}%. ${esc(s.dateNote)}</title></circle><text x="${x}" y="${i===3?245:229}" text-anchor="middle" font-size="10" fill="#677b77">${date(s).replace(', 2025','').replace(', 2026','')}${marker(s)}</text>`});$('trajectory').innerHTML=svg+'</svg>';
$('visitValues').innerHTML='<table><thead><tr><th>Reported date</th><th>Share %</th></tr></thead><tbody>'+r.values.map((v,i)=>`<tr><td>${date(data.samples[i])}${marker(data.samples[i])}</td><td>${pct(v)}</td></tr>`).join('')+'</tbody></table>';
const matches=cards.map(c=>({c,match:evidenceMatch(c,r,$('level').value)})).filter(v=>v.match).sort((a,b)=>Number(b.match.startsWith('Species'))-Number(a.match.startsWith('Species')));
$('evidence').innerHTML=matches.length?matches.map(({c,match})=>`<article class="evidence-card"><div class="kind">${esc(c.type)} · ${c.year}</div><span class="match-badge">${esc(match)}</span><h4>${esc(c.claim)}</h4><p><b>Study context:</b> ${esc(c.context)}</p><p><b>How this relates to the delta:</b> ${esc(c.deltaMeaning)}</p><p class="caution">${esc(c.limits)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.title)} ↗</a></article>`).join(''):`<div class="notice">${r.resolved?($('level').value==='family'?'Family grouping is broader than our taxon evidence. Expand the member table to inspect genus or species context.':'No reviewed evidence card is available for this feature yet. This is a coverage gap, not evidence of no biological role.'):'This label is unresolved. Species- or genus-specific evidence cannot be assigned reliably.'}</div>`;updateSearch();}
function updateSearch(){if(!selected)return;const query=`TITLE_ABS:"${selected.resolved?selected.name:(selected.genus||'gut microbiome')}"${$('context').value.trim()?' AND TITLE_ABS:"'+$('context').value.trim().replace(/["\\]/g,' ')+'"':''}`;$('searchLink').href='https://europepmc.org/search?query='+encodeURIComponent(query);$('searchLink').textContent=selected.resolved?'Search Europe PMC ↗':'Search broad microbiome literature ↗'}
function exportChanges(){const start=data.samples[+$('from').value],end=data.samples[+$('to').value];const header=['feature','feature_id','level','start_sample','start_reported_date','start_date_status','start_date_note','end_sample','end_reported_date','end_date_status','end_date_note','start_share_percent','end_share_percent','delta_percentage_points','fold_if_start_positive','detection_status','measure','presence_threshold_percent','minimum_visits_of_5','minimum_absolute_delta_pp','visits_at_threshold','search_filter','direction_filter'];const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[header.map(q).join(','),...visibleRows().map(r=>[r.name,r.id,$('level').value,start.id,start.date,start.dateStatus,start.dateNote,end.id,end.date,end.dateStatus,end.dateNote,r.start*100,r.end*100,r.delta,r.fold,r.status,'Normalized share of supplied SGB weights; underlying units unverified',settings().abundance,settings().minSamples,settings().minDelta,r.present,settings().query,settings().direction].map(q).join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download=`sid-${start.date}-to-${end.date}-${$('level').value}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('methodsBtn').onclick=()=>$('methods').showModal();$('closeMethods').onclick=()=>$('methods').close();$('export').disabled=true;
try{const responses=await Promise.all([fetch('sid-data.json'),fetch('sid-evidence.json'),fetch('sid-events.json'),fetch('sid-phylogeny.json')]);if(responses.some(r=>!r.ok))throw Error('Could not load source data.');[data,cards,clinical,phylogeny]=await Promise.all(responses.map(r=>r.json()));$('sgbCount').textContent=data.features.length;const opts=data.samples.map((s,i)=>`<option value="${i}">${date(s)}${marker(s)}</option>`).join('');$('clinicalScope').innerHTML+=opts;$('from').innerHTML=opts;$('to').innerHTML=opts;$('to').value='4';$('reportLink').href=data.provenance.report;$('methodDates').innerHTML=data.samples.map(s=>`<p><b>${date(s)}${marker(s)}:</b> ${esc(s.dateNote)}</p>`).join('');$('from').onchange=()=>updateInterval('from');$('to').onchange=()=>updateInterval('to');$('level').onchange=()=>{selected=null;render()};for(const id of ['clinicalScope','nearbyDays','eventCategory'])$(id).onchange=renderClinical;for(const id of ['minAbundance','minSamples','minDelta'])$(id).oninput=renderTable;$('clearFilters').onclick=()=>{$('minAbundance').value='0';$('minSamples').value='1';$('minDelta').value='0';$('search').value='';$('direction').value='all';renderTable()};$('direction').onchange=renderTable;$('search').oninput=renderTable;$('reset').onclick=()=>{$('from').value='0';$('to').value=String(data.samples.length-1);render()};$('rows').onclick=e=>{const b=e.target.closest('[data-id]');if(b){selected=rows.find(r=>r.id===b.dataset.id);renderTable()}};$('context').oninput=updateSearch;$('export').onclick=exportChanges;$('export').disabled=false;initLongitudinal({interval:i=>{$('from').value=String(i);$('to').value=String(i+1);render()},feature:id=>{$('minAbundance').value='0';$('minSamples').value='1';$('minDelta').value='0';$('direction').value='all';$('search').value='';selected=rows.find(r=>r.id===id);renderTable();$('taxonTitle').scrollIntoView({behavior:'smooth',block:'start'})}});render()}catch(e){$('intervalStatus').textContent=e.message;$('taxonTitle').textContent='Data unavailable';for(const id of ['from','to','level','search','direction','reset'])$(id).disabled=true}
